javascript:
// Report-Tabelle (Vollansicht) -- "Projekt"-Zeilen verlinken direkt auf
// den zugrundeliegenden Project-Datensatz (data.key = Project.name aus
// report_script), damit man von der Umsatzzahl sofort zu den Auftraegen
// des Projekts springen kann. Andere Views (typ/kunde/pm) bleiben Text --
// die Kunde-Verlinkung gibt es bewusst nur im Dashboard, nicht hier.
frappe.query_reports["Projekt \u00dcbersicht"] = {
	formatter: function (value, row, column, data, default_formatter) {
		value = default_formatter(value, row, column, data);
		if (column.fieldname === "label" && data.view === "projekt" && data.key) {
			value = '<a href="/app/project/' + encodeURIComponent(data.key) + '">' + value + '</a>';
		}
		return value;
	},
};
